#!/usr/bin/env bash
# Check each role pack's size against its budget and the skill descriptions' total; exit 1 on any `over`,
# on a generator failure, and on a generated file that differs from the generator: docs/roles/<role>.md
# (a header line, then the pack) and the root AGENTS.md (the all pack, then Main's pack under one heading,
# plus one pointer line). `--write` regenerates those files from docs/roles/rules.tsv.
set -u
ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
PACK=$ROOT/bin/jg-role-pack.sh
rc=0

size() { # <label> <file> <max-lines|-> <max-bytes|->
  local l b v=ok
  l=$(wc -l < "$2"); b=$(wc -c < "$2")
  { [ "$3" != - ] && [ "$l" -gt "$3" ]; } && v=over
  { [ "$4" != - ] && [ "$b" -gt "$4" ]; } && v=over
  [ "$v" = ok ] || rc=1
  echo "$1 $l $b ${3}/${4} $v"
}

tmp=$(mktemp -d); trap 'rm -rf -- "$tmp"' EXIT
for r in all main lead worker critic; do
  "$PACK" "$r" > "$tmp/$r" || { echo "FAIL: generator failed for $r" >&2; rc=1; }
done
cat "$tmp/all" "$tmp/main" > "$tmp/allmain"
size all "$tmp/all" 80 -
size main "$tmp/main" 120 16384
size all+main "$tmp/allmain" 199 24576
size lead "$tmp/lead" 120 -
size worker "$tmp/worker" 80 8000
size critic "$tmp/critic" 60 -

# the descriptions of every skill together, in characters (budget 8000)
chars=0
for f in "$ROOT"/.agents/skills/*/SKILL.md; do
  d=$(awk 'BEGIN{fm=0;in_d=0}
    /^---$/ {fm++; if (fm==2) exit; next}
    fm==1 && /^description:/ { sub(/^description:[ \t]*(>-?|\|-?)?[ \t]*/, ""); in_d=1; if ($0!="") print; next }
    fm==1 && in_d && /^[ \t]/ { sub(/^[ \t]+/, ""); print; next }
    fm==1 { in_d=0 }' "$f")
  chars=$((chars + ${#d}))
done
v=ok; [ "$chars" -gt 8000 ] && v=over
echo "skill-descriptions - $chars 8000 $v"

# the generated files: expected content is built here, then written (--write) or diffed
ROLES=$ROOT/docs/roles
gen_role_file() { # <role> - header line, then the pack
  printf '<!-- Generated by bin/jg-role-pack.sh %s from docs/roles/rules.tsv; edit the table and run bash tests/role-pack-budget.test.sh --write. -->\n' "$1"
  cat "$tmp/$1"
}
gen_agents() {
  cat "$tmp/all"
  printf '\n# Main (the Overwatch) only\n\n'
  # shellcheck disable=SC2016 # the backticks are literal Markdown
  printf '%s\n\n' 'Squad Leads: your contract is the first block of `bin/jg-session-start.sh`. Workers and critics: your brief is your contract; the Main section is not yours.'
  cat "$tmp/main"
}
for r in main lead worker critic; do gen_role_file "$r" > "$tmp/$r.md"; done
gen_agents > "$tmp/AGENTS.md"
if [ "${1:-}" = --write ]; then
  for r in main lead worker critic; do cp "$tmp/$r.md" "$ROLES/$r.md"; done
  cp "$tmp/AGENTS.md" "$ROOT/AGENTS.md"
fi
for r in main lead worker critic; do
  cmp -s "$tmp/$r.md" "$ROLES/$r.md" || { echo "FAIL: docs/roles/$r.md differs from the generator (run with --write)" >&2; rc=1; }
done
cmp -s "$tmp/AGENTS.md" "$ROOT/AGENTS.md" || { echo "FAIL: AGENTS.md differs from the generator (run with --write)" >&2; rc=1; }
exit $rc
